  d['id']['co.faq_h2_9'] = 'Pertanyaan yang Sering Diajukan';
  d['id']['co.faq_p_1'] = 'Yes. We go beyond recommendations to guide implementation, working alongside your team through the transformation process. Our involvement can range from strategic oversight to hands-on project leadership.';
  d['id']['co.faq_p_3'] = 'Strategic planning engagements typically run 3–6 months. Restructuring and transformation projects may extend to 12+ months depending on scope and complexity. We tailor engagement timelines to your specific needs.';
  d['id']['co.faq_p_5'] = 'Family enterprises are a core focus. We understand the unique dynamics of family businesses — including succession planning, governance structuring, next-generation leadership development, and balancing family interests with business objectives.';
  d['id']['co.faq_p_7'] = 'The right time is when you face a strategic inflection point — growth plateaus, market shifts, leadership transitions, or organizational complexity that internal teams struggle to address independently. Early engagement often prevents larger issues downstream.';
  d['id']['co.faq_span_10'] = 'Questions &amp; Answers';
  d['id']['co.faq_span_2'] = 'Does Chatura provide hands-on implementation support?';
  d['id']['co.faq_span_4'] = 'How long do typical advisory engagements last?';
