  d['id']['co.solution_h2_7'] = 'Integrated Corporate Advisory Practice';
  d['id']['co.solution_p_5'] = 'From strategic planning and Restrukturisasi Korporasi to governance design and succession planning, we provide the objective counsel and hands-on support your organization needs to transform and grow.';
  d['id']['co.solution_p_6'] = 'Our corporate advisory practice works alongside leadership teams as a trusted strategic partner. We bring external perspective, structured thinking, and deep experience to help you navigate complexity and make better decisions.';
  d['id']['co.solution_span_1'] = 'Succession';
  d['id']['co.solution_span_2'] = 'Governance';
