  d['id']['co.solution_span_8'] = 'Our Solution';
  d['id']['co.summary_h2_4'] = 'Advisory as a Catalyst for Transformation';
  d['id']['co.summary_p_1'] = 'Whether you are a family enterprise planning generational transition, a listed company undergoing strategic restructuring, or a growing organization seeking to professionalize governance and operations, Chatura provides the objective counsel, structured thinking, and hands-on support your leadership team needs.';
  d['id']['co.summary_p_2'] = 'Our advisory team brings deep experience across Restrukturisasi Korporasi, governance design, succession planning, and operational improvement. We don\\\'t deliver generic frameworks — we tailor every engagement to your organization\\\'s unique context, culture, and strategic objectives.';
  d['id']['co.summary_p_3'] = 'At Chatura Indonesia, our Corporate Advisory practice is built on the principle that the best strategic decisions come from combining internal leadership insight with external specialist perspective. We work alongside C-suites, boards, and business owners to navigate complexity, manage change, and unlock sustainable growth.';
  d['id']['co.summary_span_5'] = 'Our Practice';
