  d['id']['ta.faq_h2_9'] = 'Pertanyaan yang Sering Diajukan';
  d['id']['ta.faq_p_1'] = 'We serve mid-market to large enterprises, including publicly listed companies, multinational corporations, state-owned enterprises, and growing businesses with complex tax needs. Our approach scales to match your organization\\\'s complexity.';
  d['id']['ta.faq_p_3'] = 'Transfer pricing is a core specialty. We prepare local files, master files, and country-by-country reports in compliance with Indonesian regulations and OECD guidelines. We also defend transfer pricing positions during audits.';
  d['id']['ta.faq_p_5'] = 'Yes. We provide full representation in tax disputes, from administrative objections through the Tax Court and appeals process. Our team has extensive experience defending client positions and achieving favorable outcomes.';
  d['id']['ta.faq_p_7'] = 'Our tax team monitors regulatory developments continuously through direct engagement with tax authorities, professional networks, and ongoing training programs. We provide proactive briefings to clients before new regulations take effect.';
