  d['id']['ta.solution_p_5'] = 'From corporate income tax compliance and transfer pricing documentation to international tax structuring and dispute resolution, we provide the full spectrum of tax services required to protect your business and enhance value.';
  d['id']['ta.solution_p_6'] = 'Our tax practice combines deep regulatory knowledge with practical business understanding. We help you stay compliant while optimizing your tax position — turning tax from a burden into a strategic advantage.';
