  d['id']['ta.summary_h2_4'] = 'Advisory Perpajakan as a Strategic Advantage';
  d['id']['ta.summary_p_1'] = 'Whether you are a multinational navigating Indonesia\\\'s transfer pricing requirements, a listed company managing complex tax obligations, or a growing enterprise seeking to optimize your effective tax rate, Chatura delivers the precision, foresight, and strategic guidance your business demands.';
  d['id']['ta.summary_p_2'] = 'Our team works closely with CFOs, tax directors, and business owners to ensure full compliance while identifying legitimate optimization opportunities. From corporate income tax and VAT to transfer pricing documentation and cross-border structuring, we provide comprehensive tax services that protect your business and enhance shareholder value.';
  d['id']['ta.summary_p_3'] = 'At Chatura Indonesia, our Tax Services practice is built on the principle that proactive tax management is not merely a compliance obligation — it is a strategic advantage. We combine deep knowledge of Indonesian tax law with international tax expertise to help businesses navigate an increasingly complex regulatory landscape.';
  d['id']['ta.summary_span_5'] = 'Our Practice';
